from datetime import datetime, timedelta
from wildlife.store import Store
from wildlife.stats import recent_count


def test_explicit_now():
    s = Store()
    now = datetime(2026, 1, 1, 12)
    s.add("zebra", now - timedelta(hours=1))
    s.add("zebra", now - timedelta(hours=30))
    assert recent_count(s, now=now) == 1


def test_default_window_uses_utc_on_non_utc_server(monkeypatch):
    # Server whose local clock is 8 hours ahead of UTC (e.g. Asia/Shanghai).
    class FakeDatetime(datetime):
        @classmethod
        def now(cls, tz=None):
            if tz is None:
                return datetime.utcnow() + timedelta(hours=8)
            return datetime.now(tz)

    monkeypatch.setattr("wildlife.stats.datetime", FakeDatetime)

    s = Store()
    now_utc = datetime.utcnow()
    s.add("deer", now_utc - timedelta(hours=1))
    s.add("deer", now_utc - timedelta(hours=30))
    assert recent_count(s) == 1

